namespace sv_93bf74122f9648e99437aa4f2a721451.Services;

/// <summary>
/// Scoped service that holds the current warehouse selection for a single user circuit.
/// Notifies all subscribers when the selection changes.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId != value)
            {
                _currentWarehouseId = value;
                NotifyStateChanged();
            }
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public static IReadOnlyList<Warehouse> Warehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

public record Warehouse(string Id, string Name);

namespace sv_93bf74122f9648e99437aa4f2a721451.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for a single user circuit.
/// Polls every 10 seconds when active and notifies all subscribers of new data.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private Timer? _timer;
    private int _subscriberCount;
    private int _currentAlertCount;
    private readonly Random _random = new();
    private readonly Lock _lock = new();

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    public int CurrentAlertCount => _currentAlertCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Call when a component wants to receive polling updates.
    /// Starts the timer on the first subscriber.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling updates.
    /// Stops the timer when the last subscriber leaves.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _timer?.Dispose();
                _timer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _currentAlertCount = count;
        await NotifySubscribers();
    }

    private async void HandleWarehouseChanged()
    {
        // When warehouse changes, immediately re-poll if active
        if (_subscriberCount > 0)
        {
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _currentAlertCount = count;
            await NotifySubscribers();
        }
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _timer?.Dispose();
    }
}

