@using sv_93bf74122f9648e99437aa4f2a721451.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouseSelect" class="form-label mb-0 me-2 text-white">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto; display: inline-block;"
            @bind="SelectedWarehouseId">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private string SelectedWarehouseId
    {
        get => WarehouseState.CurrentWarehouseId;
        set => WarehouseState.CurrentWarehouseId = value;
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

@using sv_93bf74122f9648e99437aa4f2a721451.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (AlertService.CurrentAlertCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.CurrentAlertCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

@page "/dashboard"
@using sv_93bf74122f9648e99437aa4f2a721451.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <h5 class="mb-0">Current Site: @WarehouseState.CurrentWarehouseName</h5>
    </div>
    <div class="card-body">
        <p>Warehouse ID: <code>@WarehouseState.CurrentWarehouseId</code></p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentAlertCount > 5 ? "border-danger" : "border-success")">
            <div class="card-header">
                <h5 class="mb-0">Low Stock Alerts</h5>
            </div>
            <div class="card-body text-center">
                <h2 class="@(AlertService.CurrentAlertCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.CurrentAlertCount
                </h2>
